return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'Woocommerce','Go to Plugin Search' => 'प्लगइन खोज पर जाएं','Activate %s' => '%s सक्रिय करें','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s के लिए</strong> <strong>%2$s का</strong> इंस्टॉल और सक्रिय होना आवश्यक है। <a href="%4$s">%3$s</a>','Enter your code here' => 'अपना कोड यहां दर्ज करें','Add %s' => '%s जोड़ें','Remove' => 'निकालना','Order number and receipt will be sent to this email address.' => 'ऑर्डर संख्या और रसीद इस ईमेल पते पर भेजी जाएगी।','Apartment, unit, building, floor, etc.' => 'अपार्टमेंट, इकाई, इमारत, मंजिल, आदि।','Shipping phone' => 'शिपिंग फ़ोन','Only used for shipping-related questions.' => 'केवल शिपिंग से संबंधित प्रश्नों के लिए उपयोग किया जाता है।','Single step' => 'एकल चरण','Click to go to the order summary' => 'ऑर्डर सारांश पर जाने के लिए क्लिक करें','Cart total:' => 'कार्ट का कुल योग:','Proceed to %s' => '%s पर आगे बढ़ें','Proceed to contact' => 'संपर्क करने के लिए आगे बढ़ें','Proceed to shipping' => 'शिपिंग के लिए आगे बढ़ें','Proceed to billing' => 'बिलिंग के लिए आगे बढ़ें','Proceed to payment' => 'भुगतान के लिए आगे बढ़ें','Shipping method' => 'शिपिंग का तरीका','Additional notes' => 'अतिरिक्त टिप्पणी','Payment method' => 'भुगतान विधि','Step %1$s of %2$s' => 'चरण %1$s का %2$s','Change: %s' => 'परिवर्तन: %s','Not selected yet.' => 'अभी तक चयनित नहीं.','Same as shipping address' => 'शिपिंग पते के समान','Same as billing address' => 'बिलिंग पते के समान','Order summary' => 'आदेश सारांश','Edit cart' => 'कार्ट संपादित करें','Did you mean %s?' => 'क्या आपका मतलब %s था?','Change email address to: {suggestion-value}' => 'ईमेल पता बदलें: {suggestion-value}','This is a required field.' => 'यह एक अपेक्षित क्षेत्र है।','This is not a valid email address.' => 'यह कोई मान्य ईमेल पता नहीं है।','This field does not match the related field value.' => 'यह फ़ील्ड संबंधित फ़ील्ड मान से मेल नहीं खाता.','The CPF number "{cpf_number}" is invalid.' => 'CPF संख्या &quot;{cpf_number}&quot; अमान्य है.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ संख्या &quot;{cnpj_number}&quot; अमान्य है.','(Required)' => '(आवश्यक)','Checkout Header - Desktop' => 'चेकआउट हेडर - डेस्कटॉप','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'बड़ी स्क्रीन के लिए चेकआउट हेडर पर विजेट प्रदर्शित करें। प्लगइन के चेकआउट हेडर का उपयोग करने पर ही प्रदर्शित करें।','Checkout Header - Mobile' => 'चेकआउट हेडर - मोबाइल','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'मोबाइल डिवाइस के लिए चेकआउट हेडर के नीचे विजेट प्रदर्शित करें। प्लगइन के चेकआउट हेडर का उपयोग करने पर ही प्रदर्शित करें।','Checkout Sidebar' => 'चेकआउट साइडबार','Display widgets on the checkout sidebar after the order summary.' => 'ऑर्डर सारांश के बाद चेकआउट साइडबार पर विजेट प्रदर्शित करें।','Checkout Order Summary' => 'चेकआउट ऑर्डर सारांश','Display widgets inside the order summary at the checkout page.' => 'चेकआउट पृष्ठ पर ऑर्डर सारांश के अंदर विजेट प्रदर्शित करें।','Checkout Below Place Order' => 'नीचे चेकआउट करें ऑर्डर दें','Display widgets below the place order button at the checkout page.' => 'चेकआउट पृष्ठ पर ऑर्डर स्थान बटन के नीचे विजेट प्रदर्शित करें।','Checkout Footer' => 'चेकआउट फ़ुटर','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'चेकआउट फ़ुटर पर विजेट प्रदर्शित करें। केवल प्लगइन के चेकआउट फ़ुटर का उपयोग करने पर ही प्रदर्शित करें।','Classic' => 'क्लासिक','Boxed' => 'बॉक्स्ड','Split' => 'विभाजित करना','Minimalist' => 'minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'कोडरॉकज़ द्वारा फ्लूइड चेकआउट और डिलीवरी डेट प्लगइन्स','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>हमने पाया है कि आप CodeRockz द्वारा WooCommerce (फ्री और प्रो) के लिए डिलीवरी और पिकअप डेट टाइम प्लगइन का उपयोग कर रहे हैं। इन प्लगइन के साथ एकीकरण को Fluid Checkout PRO में स्थानांतरित कर दिया गया है।</p>','Upgrade to PRO' => 'प्रो में अपग्रेड','Fluid Checkout database updated successfully' => 'फ्लूइड चेकआउट डेटाबेस सफलतापूर्वक अपडेट किया गया','The database changes where applied successfully.' => 'डेटाबेस में परिवर्तन सफलतापूर्वक लागू किया गया।','Dismiss' => 'नकार देना','Fluid Checkout database update' => 'द्रव चेकआउट डेटाबेस अद्यतन','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'डेटाबेस में कुछ बदलाव ज़रूरी हैं। किसी भी अपडेट की तरह, हम आपको सलाह देते हैं कि <strong>आगे बढ़ने से पहले अपनी वेबसाइट का पूरा बैकअप ले लें</strong> ।','Update database' => 'डेटाबेस अपडेट करें','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'फ्लुइड चेकआउट डिवी बिल्डर चेकआउट लेआउट के साथ संगत नहीं है','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>फ्लूइड चेकआउट को काम करने के लिए क्लासिक WooCommerce शॉर्टकोड-आधारित चेकआउट फ़ॉर्म की आवश्यकता होती है। चेकआउट पेज के लुक और फील को कस्टमाइज़ करने के लिए Divi Builder का उपयोग करते समय, चेकआउट पेज के प्रत्येक भाग के लिए क्लासिक शॉर्टकोड को Divi Builder से कस्टम विजेट से बदल दिया जाता है। ये कस्टम विजेट Fluid Checkout के साथ संगत नहीं हैं।</p><p> कृपया अपने चेकआउट पृष्ठ को संपादित करें और Divi बिल्डर विजेट को शॉर्टकोड <code>[woocommerce_checkout]</code> युक्त टेक्स्ट विजेट से बदलें।</p>','Edit the checkout page' => 'चेकआउट पृष्ठ संपादित करें','Read the documentation.' => 'दस्तावेज़ पढ़ें.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'फ़्लूइड चेकआउट का उपयोग करते समय जर्मनकृत प्रो मल्टीस्टेप चेकआउट सुविधा को अक्षम करना आवश्यक है','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'फ्लूइड चेकआउट का उपयोग करते समय, जर्मनकृत प्रो प्लगइन से मल्टीस्टेप सुविधा अनावश्यक हो जाती है और <strong>नए ऑर्डर संसाधित करते समय गंभीर त्रुटियाँ</strong> पैदा कर सकती है। कृपया प्लगइन सेटिंग्स में जर्मनकृत प्रो मल्टीस्टेप चेकआउट सुविधा को अक्षम करें।','Go to Germanized settings' => 'जर्मनकृत सेटिंग्स पर जाएं','Thanks for choosing Fluid Checkout!' => 'फ्लूइड चेकआउट चुनने के लिए धन्यवाद!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'आप कुछ समय से इस प्लगइन का उपयोग कर रहे हैं। अब तक आपको यह कैसा लगा?<br> कृपया हमें शीघ्र रेटिंग दें, हम आपकी हर प्रतिक्रिया की सराहना करते हैं और यह हमें प्लगइन में सुधार जारी रखने के लिए प्रोत्साहित करती है :)','Rate the plugin' => 'प्लगइन को रेटिंग दें','I need help!' => 'मुझे मदद की ज़रूरत है!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Quadlayers द्वारा WooCommerce Checkout Manager की कुछ विशेषताएं Fluid Checkout के साथ उपयोग करने पर अपेक्षित रूप से काम नहीं कर सकती हैं। अधिक जानकारी और वैकल्पिक समाधानों के लिए <a href="%s">हमारा दस्तावेज़</a> पढ़ें।','Read documentation' => 'दस्तावेज़ पढ़ें','Don\'t show this again' => 'इसे दोबारा न दिखाएं','Fluid Checkout PRO' => 'फ्लूइड चेकआउट प्रो','More design templates' => 'अधिक डिज़ाइन टेम्पलेट्स','Optimized cart page' => 'अनुकूलित कार्ट पृष्ठ','Optimized order received / thank you page' => 'अनुकूलित आदेश प्राप्ति / धन्यवाद पृष्ठ','Edit cart contents at checkout page' => 'चेकआउट पृष्ठ पर कार्ट सामग्री संपादित करें','Account matching / user matching' => 'खाता मिलान / उपयोगकर्ता मिलान','Trust symbols on the cart and thank you pages' => 'कार्ट और धन्यवाद पृष्ठों पर विश्वास प्रतीक','More positions for the coupon code on the checkout page' => 'चेकआउट पृष्ठ पर कूपन कोड के लिए अधिक स्थान','International phone numbers' => 'अंतर्राष्ट्रीय फ़ोन नंबर','Gift messages and packing slips' => 'उपहार संदेश और पैकिंग पर्चियां','Local pickup and in-store collection' => 'स्थानीय पिकअप और स्टोर में संग्रहण','EU-VAT Assistant' => 'EU-VAT सहायक','I already have it – Hide this offer' => 'मेरे पास यह पहले से ही है – इस ऑफ़र को छिपाएँ','Activated' => 'सक्रिय','Address book' => 'पता पुस्तिका','Select an image' => 'एक छवि चुनें','Cart layout' => 'कार्ट लेआउट','Cart optimizations' => 'कार्ट अनुकूलन','Enable cart page optimizations' => 'कार्ट पेज अनुकूलन सक्षम करें','Header and footer template' => 'शीर्षलेख और पादलेख टेम्पलेट','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'यह नियंत्रित करता है कि विकर्षण मुक्त पृष्ठ शीर्षलेख और पादलेख का उपयोग किया जाए या वर्तमान में सक्रिय थीम के शीर्षलेख और पादलेख को रखा जाए।','Distraction free header and footer' => 'विकर्षण मुक्त हेडर और फ़ुटर','Theme\'s header and footer' => 'थीम का शीर्षलेख और पादलेख','Cart elements' => 'कार्ट तत्व','Make the order summary stay visible on the cart page while scrolling' => 'स्क्रॉल करते समय ऑर्डर सारांश को कार्ट पेज पर दृश्यमान बनाए रखें','Coupon codes' => 'कूपन कोड','Hidden' => 'छिपा हुआ','Before the cart items section' => 'कार्ट आइटम अनुभाग से पहले','Inside the cart items section' => 'कार्ट आइटम अनुभाग के अंदर','After the cart items section' => 'कार्ट आइटम अनुभाग के बाद','Before the shipping section' => 'शिपिंग अनुभाग से पहले','After the shipping section' => 'शिपिंग अनुभाग के बाद','Before the order summary' => 'ऑर्डर सारांश से पहले','Inside the order summary' => 'ऑर्डर सारांश के अंदर','Before the order totals' => 'ऑर्डर के कुल योग से पहले','After the order totals' => 'ऑर्डर के कुल योग के बाद','After the order summary' => 'ऑर्डर सारांश के बाद','Shipping' => 'शिपिंग','Select position where to display the shipping costs and calculator on the cart page.' => 'वह स्थान चुनें जहां कार्ट पृष्ठ पर शिपिंग लागत और कैलकुलेटर प्रदर्शित किया जाए।','Display as a cart section' => 'कार्ट अनुभाग के रूप में प्रदर्शित करें','Cross-sells' => 'क्रॉस-बेचता है','Select position where to display the cross-sells section on the cart page.' => 'वह स्थान चुनें जहां कार्ट पृष्ठ पर क्रॉस-सेल्स अनुभाग प्रदर्शित करना है।','Before the cart actions' => 'कार्ट क्रिया से पहले','After the cart actions' => 'कार्ट क्रिया के बाद','Layout of cross-sell items on the cart page.' => 'कार्ट पृष्ठ पर क्रॉस-सेल आइटम का लेआउट।','Optimized horizontal cross-sells layout' => 'अनुकूलित क्षैतिज क्रॉस-सेल्स लेआउट','Theme\'s cross-sells layout' => 'थीम का क्रॉस-सेल्स लेआउट','Number of cross-sell items to display on the cart page' => 'कार्ट पेज पर प्रदर्शित करने के लिए क्रॉस-सेल आइटम की संख्या','Add widget areas to the cart page' => 'कार्ट पेज पर विजेट क्षेत्र जोड़ें','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'इन विजेट क्षेत्रों का उपयोग कार्ट पृष्ठ पर ट्रस्ट प्रतीक और ट्रस्ट बैज जोड़ने के लिए किया जाता है।','Checkout' => 'चेक आउट','Checkout layout' => 'चेकआउट लेआउट','Design template' => 'डिज़ाइन टेम्पलेट','Dark mode' => 'डार्क मोड','Enable dark mode' => 'डार्क मोड सक्षम करें','Logo image' => 'लोगो छवि','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'चेकआउट पेज हेडर पर प्रदर्शित करने के लिए एक छवि चुनें। यह केवल तभी लागू होता है जब विकर्षण मुक्त हेडर और फ़ुटर का उपयोग किया जाता है।','Header background color' => 'हेडर पृष्ठभूमि रंग','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'चेकआउट पेज हेडर के लिए पृष्ठभूमि रंग चुनें। यह केवल तभी लागू होता है जब ध्यान भटकाने वाले हेडर और फ़ूटर का उपयोग किया जाता है।','HTML color value. ie: #f3f3f3' => 'HTML रंग मान. यानी: #f3f3f3','Page background color' => 'पृष्ठ पृष्ठभूमि रंग','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'चेकआउट पेज के लिए पृष्ठभूमि रंग चुनें। रंग <em>बॉडी</em> तत्व पर लागू होता है।','Footer background color' => 'पाद लेख पृष्ठभूमि रंग','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'चेकआउट पेज फ़ुटर के लिए पृष्ठभूमि रंग चुनें। यह केवल तभी लागू होता है जब ध्यान भटकाने वाले हेडर और फ़ुटर का उपयोग किया जाता है।','Progress bar' => 'प्रोगेस बार','Display the checkout progress bar when using multi-step checkout layout' => 'बहु-चरणीय चेकआउट लेआउट का उपयोग करते समय चेकआउट प्रगति बार प्रदर्शित करें','Make the checkout progress bar stay visible while scrolling' => 'स्क्रॉल करते समय चेकआउट प्रगति बार को दृश्यमान बनाए रखें','Express checkout' => 'स्पष्ट नियंत्रण','Enable the express checkout section' => 'एक्सप्रेस चेकआउट अनुभाग सक्षम करें','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'जब समर्थित भुगतान गेटवे में यह सुविधा सक्षम होती है, तो चेकआउट के समय एक्सप्रेस चेकआउट अनुभाग प्रदर्शित होता है।','Display express checkout buttons in one line for larger screens' => 'बड़ी स्क्रीन के लिए एक्सप्रेस चेकआउट बटन को एक पंक्ति में प्रदर्शित करें','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'संगत एक्सप्रेस चेकआउट भुगतान गेटवे से भुगतान करते समय अतिरिक्त चेकआउट आवश्यक फ़ील्ड को अनदेखा करें','Make the order summary stay visible while scrolling' => 'स्क्रॉल करते समय ऑर्डर सारांश को दृश्यमान बनाए रखें','Choose a background color for the order summary section.' => 'ऑर्डर सारांश अनुभाग के लिए पृष्ठभूमि रंग चुनें.','Highlight the order totals row in the order summary table' => 'ऑर्डर सारांश तालिका में ऑर्डर योग पंक्ति को हाइलाइट करें','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'यह तब सबसे उपयोगी होता है जब ऑर्डर सारांश अनुभाग में हाइलाइट किया गया बैकग्राउंड रंग नहीं होता है। फ़्लूइड चेकआउट प्रो का उपयोग करते समय कार्ट, ऑर्डर प्राप्त और ऑर्डर देखें पृष्ठों पर भी लागू हो सकता है।','Action link on the order summary at checkout.' => 'चेकआउट के समय ऑर्डर सारांश पर कार्रवाई लिंक।','Edit cart link' => 'कार्ट लिंक संपादित करें','Cart items count' => 'कार्ट आइटम की संख्या','Link to shop page' => 'दुकान पृष्ठ का लिंक','Cart items' => 'कार्ट आइटम','Hide cart items errors at the checkout page' => 'चेकआउट पृष्ठ पर कार्ट आइटम त्रुटियाँ छिपाएँ','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'चेकआउट पेज के शीर्ष पर कार्ट आइटम त्रुटि संदेश प्रदर्शित न करें। खरीदारी पूरी करने के लिए चेकआउट फ़ॉर्म सबमिट करते समय, ये त्रुटि संदेश हमेशा प्रदर्शित होंगे।','Place order' => 'आदेश देना','Define the position to display "Place order" and terms checkbox section.' => '&quot;ऑर्डर दें&quot; और शर्तें चेकबॉक्स अनुभाग प्रदर्शित करने के लिए स्थिति को परिभाषित करें।','Some options might not be compatible with some plugins and themes.' => 'कुछ विकल्प कुछ प्लगइन्स और थीम्स के साथ संगत नहीं हो सकते हैं।','Below the payment section' => 'भुगतान अनुभाग के नीचे','Below the order summary' => 'आदेश सारांश के नीचे','Both below the payment section and the order summary' => 'भुगतान अनुभाग और ऑर्डर सारांश दोनों के नीचे','Add widget areas to the checkout page' => 'चेकआउट पृष्ठ पर विजेट क्षेत्र जोड़ें','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'इन विजेट क्षेत्रों का उपयोग चेकआउट पृष्ठ पर ट्रस्ट प्रतीक और ट्रस्ट बैज जोड़ने के लिए किया जाता है।','Display the coupon codes section title' => 'कूपन कोड अनुभाग शीर्षक प्रदर्शित करें','Select position where to display the coupon codes section on the checkout page.' => 'चेकआउट पृष्ठ पर कूपन कोड अनुभाग प्रदर्शित करने के लिए स्थान का चयन करें।','Before the checkout steps' => 'चेकआउट से पहले के चरण','As a substep before payment methods' => 'भुगतान विधियों से पहले एक उप-चरण के रूप में','As a substep after payment methods' => 'भुगतान विधियों के बाद एक उपचरण के रूप में','Default button style' => 'डिफ़ॉल्ट बटन शैली','"Add" link button' => '&quot;जोड़ें&quot; लिंक बटन','Checkout fields' => 'चेकआउट फ़ील्ड','Optional fields' => 'वैकल्पिक क्षेत्र','Hide optional fields behind a link button' => 'लिंक बटन के पीछे वैकल्पिक फ़ील्ड छिपाएँ','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'खुले इनपुट फ़ील्ड की संख्या को कम करने के लिए इस विकल्प को चेक रखने की अनुशंसा की जाती है, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">शोध पढ़ें</a> ।','Do not hide "Address line 2" fields behind a link button' => '&quot;पता पंक्ति 2&quot; फ़ील्ड को लिंक बटन के पीछे न छिपाएं','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'यह केवल तभी अनुशंसित किया जाता है जब अधिकांश ग्राहकों को वास्तव में &quot;पता पंक्ति 2&quot; फ़ील्ड की आवश्यकता होती है, या जब सही शिपिंग पता प्राप्त करना महत्वपूर्ण होता है (अर्थात यदि भोजन और अन्य जल्दी खराब होने वाले उत्पादों की डिलीवरी की जा रही हो)।','Billing address' => 'बिलिंग पता','Select position where to display the billing address section on the checkout page.' => 'चेकआउट पृष्ठ पर बिलिंग पता अनुभाग प्रदर्शित करने के लिए स्थान का चयन करें।','As a step before shipping' => 'शिपिंग से पहले एक कदम के रूप में','As a sub-step before the shipping address section' => 'शिपिंग पता अनुभाग से पहले एक उप-चरण के रूप में','As a sub-step after the shipping address section' => 'शिपिंग पता अनुभाग के बाद एक उप-चरण के रूप में','As a step after shipping' => 'शिपिंग के बाद एक कदम के रूप में','As a sub-step before the payment section' => 'भुगतान अनुभाग से पहले एक उप-चरण के रूप में','Force billing and shipping addresses to the same (single section)' => 'बिलिंग और शिपिंग पते को एक ही (एकल अनुभाग) पर बाध्य करें','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;शिपिंग/बिलिंग पते के समान&quot; के लिए चेकबॉक्स डिफ़ॉल्ट रूप से चेक किया गया है','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'जब शिपिंग पता अनुभाग सबसे पहले प्रदर्शित होगा, तो चेकबॉक्स &quot;शिपिंग पते के समान&quot; डिफ़ॉल्ट रूप से चेक किया हुआ दिखाई देगा।<br> जब बिलिंग पता अनुभाग सबसे पहले प्रदर्शित होगा तो चेकबॉक्स &quot;बिलिंग पते के समान&quot; डिफ़ॉल्ट रूप से चेक किया हुआ दिखाई देगा।<br> <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">शोध में कहा गया है कि</a> चेकआउट के समय खुले इनपुट फ़ील्ड की संख्या को काफी कम करने के लिए इस विकल्प को चेक करके छोड़ने की अनुशंसा की जाती है।','Highlight the billing address section in the checkout form' => 'चेकआउट फ़ॉर्म में बिलिंग पता अनुभाग को हाइलाइट करें','Shipping address' => 'शिपिंग पता','Highlight the shipping address section in the checkout form' => 'चेकआउट फ़ॉर्म में शिपिंग पता अनुभाग को हाइलाइट करें','Shipping methods' => 'शिपिंग विधियां','Choose in which position to display the shipping methods section.' => 'शिपिंग विधि अनुभाग को किस स्थान पर प्रदर्शित करना है, इसका चयन करें।','Before shipping address' => 'शिपिंग से पहले का पता','After shipping address' => 'शिपिंग पते के बाद','Local pickup' => 'खुद जाकर ले आना','Removes shipping address section when a local pickup shipping method is selected.' => 'स्थानीय पिकअप शिपिंग विधि का चयन करने पर शिपिंग पता अनुभाग हटा देता है.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'जब स्थानीय पिकअप शिपिंग विधि का चयन किया जाता है, तो शिपिंग पते को पिकअप बिंदु स्थान से बदल दिया जाता है।','Choose which address to save as the shipping address for local pickup orders.' => 'स्थानीय पिकअप ऑर्डर के लिए शिपिंग पते के रूप में कौन सा पता सहेजना है, इसका चयन करें।','Save the selected pickup location' => 'चयनित पिकअप स्थान को सहेजें','Save same as the billing address' => 'बिलिंग पते के समान ही सहेजें','Do not save any shipping address' => 'कोई भी शिपिंग पता न सहेजें','Company name field for shipping address' => 'शिपिंग पते के लिए कंपनी का नाम फ़ील्ड','Change visibility for the company name field for the shipping address section on the checkout form.' => 'चेकआउट फ़ॉर्म पर शिपिंग पता अनुभाग के लिए कंपनी नाम फ़ील्ड की दृश्यता बदलें।','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'यदि फ़ील्ड को &quot;वैकल्पिक&quot; के रूप में सेट किया गया है, जो कि डिफ़ॉल्ट दृश्यता स्थिति है, तो अन्य प्लगइन्स को आवश्यक परिवर्तन लागू करने की अनुमति देने के लिए कोई भी परिवर्तन लागू नहीं किया जाएगा।','Hidden (remove field)' => 'छुपा हुआ (फ़ील्ड हटाएं)','Optional' => 'वैकल्पिक','Required' => 'आवश्यक','Add shipping phone field to the checkout form.' => 'चेकआउट फ़ॉर्म में शिपिंग फ़ोन फ़ील्ड जोड़ें.','Choose in which step to display the shipping phone field.' => 'शिपिंग फ़ोन फ़ील्ड को किस चरण में प्रदर्शित करना है, इसका चयन करें.','Contact step' => 'संपर्क चरण','Billing phone' => 'बिलिंग फ़ोन','Add billing phone field to the checkout form.' => 'चेकआउट फ़ॉर्म में बिलिंग फ़ोन फ़ील्ड जोड़ें.','Choose in which step to display the billing phone field.' => 'बिलिंग फ़ोन फ़ील्ड को किस चरण में प्रदर्शित करना है, इसका चयन करें.','Show country code beside the flag' => 'ध्वज के बगल में देश कोड दिखाएं','Show an example of a valid phone number inside phone fields' => 'फ़ोन फ़ील्ड के अंदर मान्य फ़ोन नंबर का उदाहरण दिखाएँ','Do not change placeholders' => 'प्लेसहोल्डर्स को न बदलें','Show if not defined' => 'यदि परिभाषित न हो तो दिखाएं','Always show' => 'हमेशा दिखाएं','Order notes' => 'ऑर्डर नोट','Define the visibility of the additional order notes field.' => 'अतिरिक्त ऑर्डर नोट्स फ़ील्ड की दृश्यता परिभाषित करें.','Gift options' => 'उपहार विकल्प','Allow customers to add a gift message and other gift related options to the order.' => 'ग्राहकों को ऑर्डर में उपहार संदेश और अन्य उपहार संबंधी विकल्प जोड़ने की अनुमति दें।','Display the gift message as part of the order details table instead of a separate section' => 'उपहार संदेश को अलग अनुभाग के बजाय ऑर्डर विवरण तालिका के भाग के रूप में प्रदर्शित करें','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'यह विकल्प ऑर्डर पुष्टिकरण पृष्ठ (धन्यवाद पृष्ठ) और खाता पृष्ठों, ईमेल और पैकिंग पर्चियों पर ऑर्डर विवरण को प्रभावित करता है।','Account matching' => 'खाता मिलान','Enable the account matching feature' => 'खाता मिलान सुविधा सक्षम करें','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'जब ग्राहक के संपर्क विवरण के साथ पहले से ही कोई खाता मौजूद हो, तो अतिथि ग्राहक के ऑर्डर को उनके मौजूदा खाते से संबद्ध करें।','Display message when an account exists with the email address provided' => 'जब दिए गए ईमेल पते के साथ कोई खाता मौजूद हो तो संदेश प्रदर्शित करें','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'खाता निर्माण फ़ील्ड को अधिसूचना और लॉग इन करने के विकल्प से प्रतिस्थापित करता है। कुछ संदर्भों में, ग्राहकों की गोपनीयता की सुरक्षा के लिए इस विकल्प को अक्षम छोड़ने की अनुशंसा की जा सकती है।','Dashboard' => 'डैशबोर्ड','Integrations' => 'एकीकरण','License keys' => 'लाइसेंस कुंजियाँ','Visit our website for more information about our plugins and add-ons.' => 'हमारे प्लगइन्स और ऐड-ऑन के बारे में अधिक जानकारी के लिए हमारी वेबसाइट पर जाएँ।','Order pay page' => 'ऑर्डर भुगतान पृष्ठ','Order pay' => 'आदेश भुगतान','Enable order pay page optimizations' => 'ऑर्डर भुगतान पृष्ठ अनुकूलन सक्षम करें','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ग्राहक से भुगतान लंबित मौजूदा ऑर्डर के लिए ऑर्डर भुगतान पृष्ठ का लेआउट बदलता है।','Add widget areas to the order pay page' => 'ऑर्डर भुगतान पृष्ठ पर विजेट क्षेत्र जोड़ें','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'इन विजेट क्षेत्रों का उपयोग ऑर्डर भुगतान पृष्ठ पर ट्रस्ट प्रतीकों और ट्रस्ट बैज जोड़ने के लिए किया जाता है।','Thank you page & order details layout' => 'धन्यवाद पृष्ठ एवं ऑर्डर विवरण लेआउट','Order details optimizations' => 'ऑर्डर विवरण अनुकूलन','Enable thank you page and order details optimizations' => 'धन्यवाद पृष्ठ और ऑर्डर विवरण अनुकूलन सक्षम करें','Changes the layout of order details on the thank you page and account pages.' => 'धन्यवाद पृष्ठ और खाता पृष्ठों पर ऑर्डर विवरण का लेआउट बदलता है।','Enable order details customizations on email notifications' => 'ईमेल सूचनाओं पर ऑर्डर विवरण अनुकूलन सक्षम करें','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ईमेल सूचनाओं पर नए अनुभाग प्रदर्शित करें और अनुभागों का क्रम बदलें। ईमेल सूचनाओं पर आदेश विवरण की शैलियाँ अपरिवर्तित रहती हैं।','Thank you page' => 'धन्यवाद पृष्ठ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ये विकल्प धन्यवाद पृष्ठ को प्रभावित करते हैं, जिसे ऑर्डर प्राप्ति या ऑर्डर पुष्टि पृष्ठ भी कहा जाता है।','Order details layout' => 'ऑर्डर विवरण लेआउट','Display the order details with wide layout on the thank you page' => 'धन्यवाद पृष्ठ पर विस्तृत लेआउट के साथ ऑर्डर विवरण प्रदर्शित करें','Add widget areas to the thank you page' => 'धन्यवाद पृष्ठ पर विजेट क्षेत्र जोड़ें','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'इन विजेट क्षेत्रों का उपयोग धन्यवाद पृष्ठ पर विश्वास प्रतीक और विश्वास बैज जोड़ने के लिए किया जाता है।','Order actions' => 'आदेश क्रियाएँ','Choose in which position to display the order actions.' => 'ऑर्डर क्रियाएँ किस स्थिति में प्रदर्शित की जाएँ, इसका चयन करें।','Inside the order overview' => 'ऑर्डर अवलोकन के अंदर','After the order overview' => 'ऑर्डर अवलोकन के बाद','After order sections' => 'आदेश अनुभागों के बाद','Order status' => 'आदेश की स्थिति','Display the order status progress bar' => 'ऑर्डर स्थिति प्रगति बार प्रदर्शित करें','Choose in which position to display the section.' => 'अनुभाग को किस स्थिति में प्रदर्शित करना है, इसका चयन करें।','After the order overview and payment instructions' => 'ऑर्डर अवलोकन और भुगतान निर्देशों के बाद','Before the order items section' => 'ऑर्डर आइटम अनुभाग से पहले','Inside the order items section' => 'ऑर्डर आइटम अनुभाग के अंदर','After the order items section' => 'ऑर्डर आइटम अनुभाग के बाद','On the sidebar' => 'साइडबार पर','Order downloads' => 'डाउनलोड का आदेश दें','Gift message' => 'उपहार संदेश','Tools' => 'औजार','Troubleshooting' => 'समस्या निवारण','Debug options' => 'डीबग विकल्प','Debug mode' => 'डिबग मोड','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'डीबग मोड का उपयोग करने से वेबसाइट का प्रदर्शन प्रभावित होता है। समस्या निवारण के दौरान ही इस विकल्प का उपयोग करें।','Load unminified assets' => 'असंक्षिप्त परिसंपत्तियाँ लोड करें','Enhanced select fields' => 'उन्नत चयन क्षेत्र','Fix automatic zoom-in on form fields' => 'फ़ॉर्म फ़ील्ड पर स्वचालित ज़ूम-इन को ठीक करें','Set <code>font-size</code> inside form fields to 16px' => 'फॉर्म फ़ील्ड के अंदर <code>font-size</code> 16px पर सेट करें','Fluid Checkout' => 'द्रव चेकआउट','Settings' => 'सेटिंग्स','Support' => 'सहायता','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'अधिक विकल्पों को अनलॉक करने के लिए <a target="_blank" href="%s">PRO में अपग्रेड करें</a> ।','(PRO)' => '(प्रो)','(experimental)' => '(प्रयोगात्मक)','Please verify your phone number.' => 'कृपया अपना फ़ोन नंबर सत्यापित करें.','The Bluehost Plugin' => 'ब्लूहोस्ट प्लगइन','Custom fields' => 'तटकर क्षेत्र','Enable custom shipping email field' => 'कस्टम शिपिंग ईमेल फ़ील्ड सक्षम करें','When enabled, the shipping email field 